        parameters: {
            query?: never;
            header?: never;
            path: {
                id: string;
                payment_id: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @example Kopi tumpah oleh kasir, refund tunai */
                    reason: string;
                    /** @example 123456 */
                    pin?: string;
                    /** @example 482913 */
                    owner_pin?: string;
                    /**
                     * Format: uuid
                     * @description Approved remote request (ADR-007) used instead of owner_pin; consumed once. 409 APPROVAL_INVALID when it does not match.
                     */
                    approval_id?: string;
                    /** @description true returns the goods to stock; false records them as waste. No default. */
                    restore_stock: boolean;
                    /**
                     * @description outlet_cash pays from the outlet cash fund (V13); 409 OUTLET_INSUFFICIENT_FUNDS when it is too low.
                     * @default cash
                     * @enum {string}
                     */
                    refund_method?: "cash" | "outlet_cash" | "bank_transfer" | "gateway";
                    /** @description Partial refund by order lines (PR 8.5a). Amount = total_amount x lines subtotal / order subtotal, so tax, service and discount follow the lines; the refund returning the last lines takes what is left. Needs idempotency_key; not allowed on a by-item split payment or a bill that is only partly paid (409 REFUND_LINES_NOT_ALLOWED); more than the payment has left answers 409 REFUND_EXCEEDS_PAYMENT. */
                    lines?: {
                        /** Format: uuid */
                        order_item_id: string;
                        quantity: number;
                    }[];
                    /** @description Required with lines; a retry with the same key returns is_idempotent_replay without refunding again. */
                    idempotency_key?: string;
                    /** @description Required for bank_transfer. */
                    bank_name?: string;
                    /** @description Required for bank_transfer; the full account number is never stored. */
                    account_last4?: string;
                    /** @description Required for bank_transfer. */
                    transfer_reference?: string;
                };
            };
        };
        responses: {
            /** @description Refund processed successfully */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        payment?: components["schemas"]["InitiatePaymentResponse"]["payment"];
                        order?: components["schemas"]["Order"];
                        /** Format: int64 */
                        refund_amount?: number;
                        open_drawer?: boolean;
                        stock_restored?: boolean;
                        is_idempotent_replay?: boolean;
                        message?: string;
                    };
                };
            };
            /** @description INVALID_STAFF_PIN or INVALID_OWNER_PIN */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description FORBIDDEN (lacks payment.refund, or bank_transfer by anyone but the owner) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Order or payment not found (or payment belongs to another order) */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description NO_OPEN_SHIFT, INSUFFICIENT_DRAWER_CASH, PAYMENT_ALREADY_REFUNDED, NOT_REFUNDABLE (payment not paid or order not fully paid yet), or REFUND_WINDOW_EXCEEDED (paid before the owner window) */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description VALIDATION_FAILED (reason, restore_stock, pin, refund_method, bank_name, account_last4, transfer_reference) or OWNER_PIN_REQUIRED (above void_refund_owner_threshold, or a cashier past the cashier refund window) */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description PIN_LOCKED, PIN_ATTEMPTS_EXCEEDED or OWNER_PIN_STORE_LIMIT */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
